/* ================= P4: Work-wise Realization (Profit Lens) — billed vs bank-verified received =================
   குறிப்பு: work-க்கு cost data இல்லை (2B-ல work reference இல்லை) — true profit கணக்கிட முடியாது;
   இது realization (வசூல்) + department deduction leakage அறிக்கை. */
function buildWorksData(){
  if(!C.recon||!C.recon.contractRows||!C.recon.contractRows.length)return null;
  var mm={},i,cb=C.recon.combined||[];
  for(i=0;i<cb.length;i++){var cc=cb[i];if(cc&&cc.contract)mm[cc.contract.id]={m:cc.matchType||'',diff:cc.amountDiff}}
  var rows=C.recon.contractRows,out=[];
  for(i=0;i<rows.length;i++){var w=rows[i]||{};
    var ded=num(w.tds)+num(w.gstTds)+num(w.withHeld)+num(w.emd)+num(w.otherDeduction);
    var inv=num(w.invoiceValue),rec=num(w.receivableAmount),got=num(w.receiptAmount);
    var mi=mm[w.id]||null;
    out.push({sNo:String(w.sNo||''),fy:String(w.fy||''),name:String(w.workName||w.party||'').trim(),place:String(w.workPlace||'').trim(),
      inv:inv,ded:ded,rec:rec,got:got,pend:rec-got,m:mi?mi.m:'',bankOk:!!(mi&&mi.m&&mi.m!=='unmatched'),
      date:String(w.receiptDate||''),tax:num(w.taxableValue)})}
  var fyOrd={'FY 22-23':1,'FY 23-24':2,'Contract work FY 24-25':3,'Contract work FY 25-26':4};
  out.sort(function(a,b){var x=fyOrd[a.fy]||9,y=fyOrd[b.fy]||9;
    if(x!==y)return x-y;
    if(x===9)return a.fy<b.fy?-1:a.fy>b.fy?1:0;
    return (parseInt(a.sNo,10)||0)-(parseInt(b.sNo,10)||0)});
  var G={},go=[];
  var T={n:out.length,inv:0,ded:0,rec:0,got:0,pend:0,ok:0};
  for(i=0;i<out.length;i++){var r=out[i];
    if(!G[r.fy]){G[r.fy]={fy:r.fy,n:0,inv:0,ded:0,rec:0,got:0,pend:0,ok:0};go.push(r.fy)}
    var g=G[r.fy];g.n++;g.inv+=r.inv;g.ded+=r.ded;g.rec+=r.rec;g.got+=r.got;g.pend+=r.pend;if(r.bankOk)g.ok++;
    T.inv+=r.inv;T.ded+=r.ded;T.rec+=r.rec;T.got+=r.got;T.pend+=r.pend;if(r.bankOk)T.ok++}
  return {rows:out,fys:go.map(function(k){return G[k]}),tot:T,lastSync:C.recon.lastSync||''};
}
